#include "uart_app.h"
#include "fsm.h"
#include <string.h>
#include <stdio.h>

// External UART handle generated by CubeMX
extern UART_HandleTypeDef huart1;

#define RX_BUFFER_SIZE 128
static char rx_buffer[RX_BUFFER_SIZE];
static uint8_t rx_index = 0;
static uint8_t rx_byte;
static volatile uint8_t cmd_ready_flag = 0;

void UART_App_Init(void)
{
    // Start receiving single byte via interrupt in non-blocking mode
    HAL_UART_Receive_IT(&huart1, &rx_byte, 1);
}

void UART_SendString(char *str)
{
    HAL_UART_Transmit(&huart1, (uint8_t *)str, strlen(str), HAL_MAX_DELAY);
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1)
    {
        // Check for Enter key (CR or LF)
        if (rx_byte == '\r' || rx_byte == '\n')
        {
            if (rx_index > 0)
            {
                rx_buffer[rx_index] = '\0';
                cmd_ready_flag = 1;
                rx_index = 0;
            }
        }
        else
        {
            if (rx_index < (RX_BUFFER_SIZE - 1))
            {
                rx_buffer[rx_index++] = rx_byte;
            }
            else
            {
                rx_index = 0; // Buffer overflow protection reset
            }
        }
        
        // Re-enable interrupt reception for the next byte
        HAL_UART_Receive_IT(&huart1, &rx_byte, 1);
    }
}

void UART_Process_Command(void)
{
    if (cmd_ready_flag)
    {
        cmd_ready_flag = 0;

        int r = 0, g = 0, y = 0;

        // Parse command: SET <RED> <GREEN> <YELLOW> (e.g., SET 30 27 3)
        if (sscanf(rx_buffer, "SET %d %d %d", &r, &g, &y) == 3)
        {
            if (FSM_ConfigNextCycle((uint8_t)r, (uint8_t)g, (uint8_t)y) == 1)
            {
                char msg[64];
                sprintf(msg, "[UART] OK: Configured -> Red:%d, Green:%d, Yellow:%d\r\n", r, g, y);
                UART_SendString(msg);
            }
            else
            {
                UART_SendString("[UART] ERROR: Invalid logic! (Red must equal Green + Yellow)\r\n");
            }
        }
        // Parse command: GET STATUS
        else if (strcmp(rx_buffer, "GET STATUS") == 0)
        {
            char msg[128];
            sprintf(msg, "[STATUS] State: %d | LaneA: %ds | LaneB: %ds | Red: %ds, Green: %ds, Yellow: %ds\r\n",
                    currentState, timeLaneA, timeLaneB, cfgRedTime, cfgGreenTime, cfgYellowTime);
            UART_SendString(msg);
        }
        else
        {
            char msg[128];
            sprintf(msg, "[UART] ERROR: Invalid command -> %s\r\n", rx_buffer);
            UART_SendString(msg);
        }
    }
}